#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "covariance.h"

void init_array(int m, int n, double *float_n, double data[32][28]) {
    int i, j;

    *float_n = (double)n;

    for (i = 0; i < 32; i++)
        for (j = 0; j < 28; j++)
            data[i][j] = ((double)i * j) / 28;
}

void print_array(int m, double cov[28][28])

{
    int i, j;

    fprintf(stderr, "==BEGIN DUMP_ARRAYS==\n");
    fprintf(stderr, "begin dump: %s", "cov");
    for (i = 0; i < m; i++)
        for (j = 0; j < m; j++) {
            if ((i * m + j) % 20 == 0)
                fprintf(stderr, "\n");
            fprintf(stderr, "%0.6lf ", cov[i][j]);
        }
    fprintf(stderr, "\nend   dump: %s\n", "cov");
    fprintf(stderr, "==END   DUMP_ARRAYS==\n");
}

int main() {

    int n = 32;
    int m = 28;

    double float_n;
    double data[32][28];
    double cov[28][28];
    double mean[28];

    init_array(m, n, &float_n, data);

    kernel_covariance(float_n, data, cov, mean);

    print_array(m, cov);

    return 0;
}
